import test from 'node:test';
import assert from 'node:assert/strict';
import { createFramer } from '../src/framer.mjs';
test('splits ordinary lines across chunks',()=>{const f=createFramer();assert.deepEqual(f.push('one\r'),[]);assert.deepEqual(f.push('\ntwo\r\n'),['one','two']);assert.deepEqual(f.finish(),[]);});
test('rejects an oversized complete frame',()=>{const f=createFramer({delimiter:'|',maxBuffer:2});assert.throws(()=>f.push('long|'),RangeError);});
